<script setup>
import { loadJson } from '../../api/jsonCache.js'
import pmtPCard from '../../components/cards/pmtPCard.vue'
import pmtRCard from '../../components/cards/pmtRCard.vue'
import pmtSCard from '../../components/cards/pmtSCard.vue'
import { ref, onMounted, computed, onUnmounted } from 'vue'

const yearConfig = {
  2024: {
    color: '#3E3146',
    text: '#F7ED01',
    file: '/files/pmt/sea2024.json',
    dataFile: '/files/pmt/data2024.json',
    matchFile: '/files/pmt/match2024.json'
  },
  2025: {
    color: '#323232',
    text: '#FF8E34',
    file: '/files/pmt/sea2025.json',
    dataFile: '/files/pmt/data2025.json',
    matchFile: '/files/pmt/match2025.json'
  },
  2026: {
    color: '#322A61',
    text: '#FFFFFF',
    file: '/files/pmt/sea2026.json',
    dataFile: '/files/pmt/data2026.json',
    matchFile: '/files/pmt/match2026.json'
  }
}

const selectedYear = ref('2026')
const activeTab = ref('预选')
const songList = ref({})
const matchList = ref({})
const rankList = ref([])

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const setRem = () => {
  const designWidth = 1550
  const clientWidth = document.documentElement.clientWidth
  const fontSize = (clientWidth / designWidth) * 100
  document.documentElement.style.fontSize = fontSize + 'px'
}

const fetchSongData = async () => {
  const filePath = yearConfig[selectedYear.value].file
  const fileRankPath = yearConfig[selectedYear.value].dataFile
  const fileMatchPath = yearConfig[selectedYear.value].matchFile
  const data = await loadJson(filePath)
  const rank = await loadJson(fileRankPath)
  const match = await loadJson(fileMatchPath)
  songList.value = data
  matchList.value = match
  rankList.value = rank
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(() => {
  setRem()
  window.addEventListener('resize', setRem)
  fetchSongData()
})

onUnmounted(() => {
  window.removeEventListener('resize', setRem)
})
</script>

<template>
  <div class="song-container">
    <div class="control-wrapper">
      <div class="year-tabs">
        <button
          :class="['year-btn', { active: selectedYear === '2025' }]"
          @click="changeYear('2025')"
          :style="{ backgroundColor: selectedYear === '2025' ? yearColor : '#f5f5f5', color: selectedYear === '2025' ? yearTextColor : '#000000' }"
        >
          2025
        </button>
        <button
          :class="['year-btn', { active: selectedYear === '2026' }]"
          @click="changeYear('2026')"
          :style="{ backgroundColor: selectedYear === '2026' ? yearColor : '#f5f5f5', color: selectedYear === '2026' ? yearTextColor : '#000000' }"
        >
          2026
        </button>
      </div>

      <div class="view-switch">
        <button
          v-for="tab in ['预选', '排名', '赛况']"
          :key="tab"
          :class="['switch-btn', { active: activeTab === tab }]"
          @click="activeTab = tab"
          :style="{ 
            backgroundColor: activeTab === tab ? yearColor : 'transparent',
            color: activeTab === tab ? yearTextColor : '#666'
          }"
        >
          {{ tab }}
        </button>
      </div>
    </div>

    <div v-if="activeTab === '排名'" class="rank-wrapper">
      <div v-for="(list, title) in rankList" :key="title" class="rank-section">
        <h2 class="rank-title" :style="{ color: yearTextColor }">
          <template v-if="title === '冠军'">
            PMT{{ selectedYear }}-3强
          </template>
          <template v-else>
            {{ ['冠军','亚军','季军'].includes(title) ? '' : `PMT${selectedYear}-${title}` }}
          </template>
        </h2>

        <pmt-r-card
          :song-data="list"
          :group-title="title"
          :main-color="yearColor"
          :text-color="yearTextColor"
        />
      </div>
    </div>

    <div v-else-if="activeTab === '预选'">
      <div class="rank-title" :style="{ color: yearTextColor }">PMT{{ selectedYear }} 预选赛晋级得分</div>
      <div class="card-grid">
        <pmt-p-card
          :song-list="songList"
          :main-color="yearColor"
          :text-color="yearTextColor"
        />
      </div>
    </div>

    <div v-else-if="activeTab === '赛况'">
        <pmt-s-card
          :song-list="matchList"
          :main-color="yearColor"
          :text-color="yearTextColor"
        />
    </div>
  </div>
</template>

<style scoped>
.song-container {
  max-width: 15rem;
  margin: 0 auto;
  padding: 0.2rem;
  user-select: none;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.2rem;
  user-select: none;
}

.grid-item {
  width: 100%;
}

:deep(.pmt-p-card),
:deep(.pmt-r-card) {
  width: 100%;
}

.control-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.1rem;
}

.year-tabs {
  display: flex;
  gap: 0.08rem;
}

.year-btn {
  padding: 0.06rem 0.16rem;
  border: none;
  font-size: 0.18rem;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
}

.view-switch {
  display: flex;
  border: 0.01rem solid #ffffff;
  overflow: hidden;
}
.switch-btn {
  padding: 0.04rem 0.14rem;
  border: none;
  font-size: 0.16rem;
  cursor: pointer;
  user-select: none;
}
.switch-btn.active {
  font-weight: bold;
}

.rank-wrapper {
  width: 100%;
  margin-top: 0.2rem;
}
.rank-section {
  margin-bottom: 0.4rem;
}
.rank-title {
  font-size: 0.32rem;
  font-weight: bold;
  margin: 0 0 0.2rem 0;
  text-align: center;    
  width: 100%;           
}
</style>